    """Return run-length encoding of the input as a list of [character, count] pairs.
    Handles empty input or None by returning an empty list.
    """
    # Treat None or empty input as empty string
    if not s:
        return []
    # Ensure we can iterate over s; if it's not a string but is iterable, convert to list of its elements
    # For strings we keep characters as is
    if isinstance(s, str):
        seq = s
    else:
        try:
            seq = list(s)
        except TypeError:
            # If not iterable, convert to string representation
            seq = str(s)
    result = []
    prev = seq[0]
    count = 1
    for ch in seq[1:]:
        if ch == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = ch
            count = 1
    result.append([prev, count])
    return result
