            else:
                field_chars.append(ch)
        else:
            if ch == '"':
                in_quotes = True
            elif ch == ',':
                fields.append(''.join(field_chars))
                field_chars = []
            else:
                field_chars.append(ch)
        i += 1
    # Append last field (or empty string if line was empty)
    fields.append(''.join(field_chars))
    return fields

