def solve(matrix):
    # Bareiss algorithm for exact integer determinant (fraction-free Gaussian elimination)
    n = len(matrix)
    if n == 0:
        return 1
    # copy matrix to avoid mutating input
    A = [row[:] for row in matrix]
    det_sign = 1
    prev = 1
    for k in range(n-1):
        # pivot selection: if zero, swap with a row below that has non-zero in same column
        if A[k][k] == 0:
            swap_row = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Bareiss update keeps intermediate values integral
                A[i][j] = (pivot * A[i][j] - A[i][k] * A[k][j]) // prev
            A[i][k] = 0
        prev = pivot
    return det_sign * A[n-1][n-1]

