    """Return the minimum number of coins needed to make up `amount` using unlimited coins from `coins`.
    If impossible, return -1. Handles edge cases such as negative amount.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non-positive coin values, as they are useless or cause infinite loops
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
                cnt = dp[a - c] + 1
                if cnt < best:
                    best = cnt
        dp[a] = best
    return dp[amount] if dp[amount] != INF else -1

