    """Count islands in a binary grid that may have rows of differing lengths.
    Cells are 4‑connected (up, down, left, right). Zero or empty grid yields 0.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False] * len(row) for row in grid ]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if visited[i][j] or grid[i][j] != 1:
