def solve(nums) -> int:
    """Return the length of the longest strictly increasing subsequence.
    Handles any iterable of comparable items; returns 0 for non‑iterable or empty input.
    Uses patience sorting (binary search) for O(n log n) time.
    """
    # Guard for non‑iterable inputs
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    # Convert to list to allow multiple passes and length check
    seq = list(iterator)
    if not seq:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in seq:
        # Find position of first element >= x (bisect_left ensures strict increase)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

