def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is a two‑element sequence [start, end]. Meetings may share a
    boundary (a meeting can start exactly when another ends). Zero‑length
    meetings (start == end) are allowed and count as a meeting.
    """
    # Normalise input and discard malformed entries
    normalized = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        # Ensure start and end are comparable (numeric) values
        try:
            _ = start <= end
        except Exception:
            continue
        normalized.append((start, end))
    if not normalized:
        return 0
    # Greedy: sort by end time, then start time for deterministic ties
    normalized.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for start, end in normalized:
        if start >= current_end:
            count += 1
            current_end = end
    return count

