def solve(s):
    n = len(s)
    if n == 0:
        return ''
    best_start = 0
    best_len = 1
    def expand(l,r):
        while l>=0 and r<n and s[l]==s[r]:
            l-=1; r+=1
        return l+1, r-1
    for i in range(n):
        # odd length
