def solve(coins, amount):
    """Return the fewest number of coins needed to make *amount* using unlimited coins from *coins*.
    If impossible (or amount is negative), return -1.
    Implements classic DP (unbounded knapsack) with O(amount * len(coins)) time.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non‑positive coin values to avoid infinite loops.
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

